import numpy as np
from scipy.optimize import least_squares
E=np.asarray(df['eps'],float);TT=np.asarray(df['T'],float);S=np.asarray(df['sigma'],float)
L=np.log(1+E)**2
prods={
 'e^p T^q':lambda p,q:E**p*TT**q,
 'e^p exp(qT)':lambda p,q:E**p*np.exp(q*TT),
 'e^p exp(-q/T)':lambda p,q:E**p*np.exp(-q/TT),
 'exp(-p e) T^q':lambda p,q:np.exp(-p*E)*TT**q,
 'e exp(-q/T) p':lambda p,q:np.exp(-p*E/TT**q),
 'e^p/(1+...)':lambda p,q:E**p/(1+q*TT),
 'e^p*T^q/(1+T)':lambda p,q:E**p*TT**q/(1+TT),
}
thirds={
 'T^r':lambda r:TT**r,
 'exp(-r/T)':lambda r:np.exp(-r/TT),
 'exp(rT)':lambda r:np.exp(r*TT),
 'T^r const':lambda r:TT**r,
}
out=[]
rng=np.random.default_rng(2)
for pk,pf in prods.items():
  for tk,tf in thirds.items():
    def rv(x):
        P=pf(x[0],x[1]); H=tf(x[2])
        A=np.c_[L,P,H,np.ones_like(E)]
        if not np.all(np.isfinite(A)): return np.full_like(S,1e3)
        c,*_=np.linalg.lstsq(A,S,rcond=None)
        return S-A@c
    best=None
    for i in range(40):
        x0=rng.normal(size=3)*2
        try:
            r=least_squares(rv,x0,max_nfev=400)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    if best is not None: out.append((np.mean(best.fun**2)/np.var(S),pk,tk,best.x.round(3)))
out.sort(key=lambda x:x[0])
for o in out[:8]: print(o)

